import re

def solve(text: str) -> list:
    return list(dict.fromkeys(re.findall(r"TKT-[0-9]{4}(?![0-9])", text)))

def solve(tone: str, topic: str) -> int:
    if tone == "negative":
        return 4 if topic == "billing" else 8
    if tone == "neutral":
        return 24
    if tone == "positive":
        return 48
    raise ValueError("Unsupported tone")

def solve(language: str, intent: str) -> str:
    codes = {
        "english": "EN",
        "french": "FR",
        "spanish": "ES",
        "german": "DE",
    }
    return codes[language.lower()] + "-" + intent

def solve(city: str) -> str:
    if city.lower() in {"lyon", "marseille", "turin", "naples"}:
        return "A"
    if city.lower() in {"seville", "valencia", "porto", "lisbon"}:
        return "B"
    return "C"

def solve(zone: str, weight_kg: int) -> int:
    delivery_days = {"A": 2, "B": 4, "C": 6}
    return delivery_days[zone] + (1 if weight_kg > 20 else 0)

def solve(intent: str, cents: int) -> str:
    if intent == "refund":
        return "auto" if cents <= 5000 else "review"
    return "none"

import re

def solve(text: str) -> list:
    return sorted({tag.lower() for tag in re.findall(r"#([A-Za-z0-9]+)", text)})

def solve(tone: str, count: int) -> int:
    score = {"positive": 2, "neutral": 0, "negative": -2}[tone]
    if tone == "positive":
        score += count
    elif tone == "negative":
        score -= count
    return max(-5, min(5, score))

def solve(country: str) -> str:
    codes = {
        "France": "+33",
        "Spain": "+34",
        "Germany": "+49",
        "Italy": "+39",
        "Portugal": "+351",
    }
    return codes.get(country, "+00")

def solve(dial: str, local: str) -> str:
    groups = [local[i:i + 3] for i in range(0, len(local), 3)]
    return dial + " " + " ".join(groups)

def solve(first: str, second: str, together: bool) -> str:
    if together:
        return f"{first} and {second} go together"
    return f"{first} and {second} are kept apart"
